{
  "headline": "FDA's records trace our supply to a plant classified OAI 1098 days before the posting",
  "headline_cites": ["D8"],
  "sentences": [
    {
      "text": "FDA first posted the valproate sodium shortage on 2020-12-30 and it remains Current as of 2026-10-21.",
      "cites": ["E32", "E30"]
    },
    {
      "text": "The Fresenius Kabi USA, LLC plant (FEI 3001833549) that supplies our 100 mg/mL 5 mL vials received an OAI classification letter dated 2017-12-28, 1098 days before the shortage posting.",
      "cites": ["D8", "E29", "E4", "E2"]
    },
    {
      "text": "That same plant also had an OAI inspection ending 2011-07-08 and another ending 2013-01-11, with later VAI inspections in 2019 and 2023.",
      "cites": ["E18", "E21", "E26", "E27"]
    },
    {
      "text": "The Hikma Pharmaceuticals USA Inc. product (500 mg/5 mL) is also listed Current on the FDA shortage list since 2020-12-30.",
      "cites": ["E31", "E15"]
    },
    {
      "text": "Hikma's Portugal plant (FEI 3002807173) had an OAI inspection ending 2014-03-28 and a Warning Letter on 2014-10-21, with the most recent VAI inspection ending 2023-04-21.",
      "cites": ["E8", "E14", "E13"]
    },
    {
      "text": "Corvale East has 3.8 days of the 100 mg/mL 5 mL vials on hand while Corvale General has 14.9 days.",
      "cites": ["D1", "D2"]
    },
    {
      "text": "The rule‑ranked option is to transfer 3 vials of 100 mg/mL 5 mL from Corvale General to Corvale East, which would leave General with 14 days and bring East to 5 days.",
      "cites": ["D10"]
    }
  ]
}
